SELECT p.PERIODDATE AS `报表日期`, p.A_STOCKSNAME AS `股票简称`, p.A_STOCKCODE AS `股票代码`, p.ITEM_NAME AS `产品名称`, ROUND(p.INCOME/10000, 3) AS `营业收入(亿元)`, p.PRI_RVNU_PCT AS `收入占营业收入比(%)`, ROUND(p.GP_RATIO, 2) AS `毛利率(%)` FROM STK_PRI_INCOME_PRODUCT p WHERE p.ISVALID = 1 AND p.RPT_TYPE = '合并' AND p.PERIODDATE = '2025-12-31 00:00:00.000' AND p.A_STOCKSNAME LIKE '%万华化学%' AND p.ITEM_NAME LIKE '%聚氨酯%' AND p.PRI_RVNU_PCT IS NOT NULL AND p.GP_RATIO IS NOT NULL ORDER BY p.PRI_RVNU_PCT DESC;
